-------------------------------------------------------------------------------------------------
------------------------------ CARGAR PUNTAS desde OTROS SERVER POR TABLA DE PASO 
-------------------------------------------------------------------------------------------------
drop sequence   "BSCL"."BSCL.Plataforma.BD.Secuencias::BolsaInstrumentoPrecios";
create sequence "BSCL"."BSCL.Plataforma.BD.Secuencias::BolsaInstrumentoPrecios" increment by 1 start with 931 minvalue 931 maxvalue 4611686018427387903 no cycle ;

delete FROM  
select * from "BSCL"."BSCL.Plataforma.BD::INS.BolsaInstrumentoPrecios" where "FechaCierre" = '2015-09-22';

/*
--- Ejecutar SOBRE RUEBAS

SELECT 
			 'Insert Into #Precios values ( ' + ''''+INS.NEMO +''''+','+
			convert (varchar,INS.PRE_CIE_DI_AC)		+ ',' + -- 	AS PrecioCierre
			convert (varchar,INS.PRE_MED_DI_AC)		+ ',' + -- 	AS PrecioMedio
			convert (varchar,INS.PRE_CIE_DI_AN)		+ ',' + -- 	AS PrecioMercadoAnterior

			convert (varchar,INS.pre_cie_di_ac)		+ ',' + -- 	AS UltimoPrecioTransado
			convert (varchar,INS.var_pre)		+ ',' + --		AS VariacionDiaria
			convert (varchar,INS.uni_tra_di_ac)		+ ',' + -- 	AS VolumenTransado
			convert (varchar,INS.monto_di_ac)		+ ',' + --	AS Montotransado
			convert (varchar,ISNULL(PUNTAS.SC_PRECIO,0)) + ',' + -- AS MEJOR PRECIO DE COMPRA
			convert (varchar,ISNULL(PUNTAS.SV_PRECIO,0)) + ');'	-- AS MEJOR PRECIO DE VENTA
		FROM RUE_tbacmi AS INS 
			LEFT OUTER JOIN  RUE_TBTOM AS PUNTAS ON(INS.NEMO = PUNTAS.NEMOTE AND PUNTAS.Mercad='AC' AND LTRIM(PUNTAS.Tipo_Liq)='' AND (PUNTAS.SC_PRECIO <> 0 or PUNTAS.SV_PRECIO <> 0))
	

--- Cargar MILA
        'Insert Into #Precios values ( ' + ''''+acmi.nemo +''''+','+ 
                convert (varchar,iext.pre_cie_di_ac) + ',' + --         AS UltimoPrecioTransado 
                convert (varchar,iext.var_pre)          + ',' + --              AS VariacionDiaria 
                convert (varchar,iext.uni_tra_di_ac)            + ',' + --      AS VolumenTransado 
                convert (varchar,iext.monto_di_ac)              + ',' + --      AS Montotransado 
                convert (varchar,ISNULL(PUNTAS.SC_PRECIO,0)) + ',' + -- AS MEJOR PRECIO DE COMPRA 
                convert (varchar,ISNULL(PUNTAS.SV_PRECIO,0)) + ');'     -- AS MEJOR PRECIO DE VENTA 
        from RUE_InstrumentosExtranjeros iext, RUE_tbacmi acmi   
                LEFT OUTER JOIN  RUE_TBTOM AS PUNTAS ON(acmi.nemo = PUNTAS.NEMOTE AND PUNTAS.Mercad='AC' AND LTRIM(PUNTAS.Tipo_Liq)='' AND (PUNTAS.SC_PRECIO <> 0 or PUNTAS.SV_PRECIO <> 0))  

        where iext.nemo COLLATE Latin1_General_CI_AS  = acmi.nemo 

--- Acciones desde RUEBAS AMAZON

select 		'Insert Into #Precios values ( ' || '''' || INS.NEMO || '''' || ',' || 
			CAST(INS.PRE_CIE_DI_AC as NVARCHAR)		|| ',' ||  -- 	AS PrecioCierre
		 
			CAST(INS.PRE_CIE_DI_AC as NVARCHAR)		|| ',' ||  -- 	AS PrecioCierre
			CAST(INS.PRE_MED_DI_AC as NVARCHAR)		|| ',' ||  -- 	AS PrecioMedio
			CAST(INS.PRE_CIE_DI_AN as NVARCHAR)		|| ',' ||  -- 	AS PrecioMercadoAnterior

			CAST(INS.pre_cie_di_ac as NVARCHAR)		|| ',' ||  -- 	AS UltimoPrecioTransado
			CAST(INS.var_pre as NVARCHAR)			|| ',' ||  --		AS VariacionDiaria
			CAST(INS.uni_tra_di_ac as NVARCHAR)		|| ',' ||  -- 	AS VolumenTransado
			CAST(INS.monto_di_ac as NVARCHAR)		|| ',' ||  --	AS Montotransado
			CAST(IfNULL(PUNTAS.SC_PRECIO,0) as NVARCHAR) || ',' ||  -- AS MEJOR PRECIO DE COMPRA
			CAST(IfNULL(PUNTAS.SV_PRECIO,0) as NVARCHAR) || ');' 	-- AS MEJOR PRECIO DE VENTA
as DATA
		FROM "RUEBAS"."TBACMI" AS INS 
			LEFT OUTER JOIN  "RUEBAS"."TBTOM" AS PUNTAS ON(INS.NEMO = PUNTAS.NEMOTE AND PUNTAS.Mercad='AC' 
			AND LTRIM(PUNTAS.Tipo_Liq)='' AND (PUNTAS.SC_PRECIO <> 0 or PUNTAS.SV_PRECIO <> 0))
	
	
*/
	
drop table #Precios;

CREATE LOCAL TEMPORARY TABLE #Precios ( "Nemotecnico" NVARCHAR(40), 
										"PrecioCierre" DECIMAL(26,8), "PrecioMedio" DECIMAL(26,8),  "PrecioMercadoAnterior" DECIMAL(26,8),
										"UltimoPrecioTransado" DECIMAL(26,8), "VariacionDiaria" DECIMAL(26,8), 
										"VolumenTransado"  DECIMAL(26,8), "Montotransado" DECIMAL(26,8),
										"MejorPrecioCompra"  DECIMAL(26,8), "MejorPrecioVenta" DECIMAL(26,8)
									  );	

