---- grabar datos de punta de instrumentos nacionales
SELECT MAX("IdBolsaInstrumentoPrecios") FROM  "BSCL"."BSCL.Plataforma.BD::INS.BolsaInstrumentoPrecios" ;
-- SELECT COUNT(*) FROM #Precios

INSERT INTO "BSCL"."BSCL.Plataforma.BD::INS.BolsaInstrumentoPrecios"
select 	"BSCL"."BSCL.Plataforma.BD.Secuencias::BolsaInstrumentoPrecios".NEXTVAL AS "IdBolsaInstrumentoPrecios", 
		--ltrim(rtrim(Ins."Nemotecnico")) ,
		Ins."IdInstrumento" 			as "IdInstrumento", 
		'BCS' 							as  "IdBolsa" ,
		PRE."PrecioCierre"				as  "PrecioCierre",
		0								as  "PrecioMayor",
		0								as  "PrecioMenor",
		PRE."UltimoPrecioTransado"		as  "UltimoPrecioTransado",
		PRE."MejorPrecioCompra" 		as  "UltimoPrecioCompra",
		PRE."MejorPrecioVenta" 			as  "UltimoPrecioVenta" ,
		'2015-09-22'					as  "FechaCierre",
		0 								as  "ValorContratoUnitario",
		0								as  "ValorContratoEntidad",
		PRE."VariacionDiaria"			as  "VariacionDiaria",
		PRE."VolumenTransado"			as  "VolumenTransado",			--var_pre? tendencia?
		PRE."Montotransado" 			as  "MontoTransado",
		PRE."PrecioMedio" 				as  "PrecioMedio",
		PRE."PrecioMercadoAnterior" 	as  "PrecioMercadoAnterior"		
FROM "BSCL"."BSCL.Plataforma.BD::INS.Instrumento" Ins, #Precios as PRE
WHERE ltrim(rtrim(Ins."Nemotecnico")) = ltrim(rtrim(PRE."Nemotecnico"))
and Ins."IdTipoInstrumento" = 'ACN';

select * FROM "BSCL"."BSCL.Plataforma.BD::INS.Instrumento" Ins, "BSCL"."BSCL.Plataforma.BD::INS.BolsaInstrumentoPrecios" PREC
WHERE ltrim(rtrim(Ins."Nemotecnico")) = 'LAN' and 
PREC."IdInstrumento" = Ins."IdInstrumento"
and PREC."FechaCierre" = '2015-09-22'
and Ins."IdTipoInstrumento" = 'ACN';

--select * from  "BSCL"."BSCL.Plataforma.BD::INS.BolsaInstrumentoPrecios"

-------------------------------------------------------------------------------------------------
------------------------------ CARGAR PUNTAS desde SERVER sql AMAZON
-------------------------------------------------------------------------------------------------
INSERT INTO "BSCL"."BSCL.Plataforma.BD::INS.BolsaInstrumentoPrecios"
select 		"BSCL"."BSCL.Plataforma.BD.Secuencias::BolsaInstrumentoPrecios".NEXTVAL AS "IdBolsaInstrumentoPrecios", 
			--			INS.NEMO
			INS."IdInstrumento" 			as "IdInstrumento", 
			'BCS' 							as  "IdBolsa" ,
			ACMI."PRE_CIE_DI_AC"			as  "PrecioCierre",		 
			0								as  "PrecioMayor",
			0								as  "PrecioMenor",			
			ACMI."PRE_CIE_DI_AC"			as  "UltimoPrecioTransado",
			PUNTAS."SC_PRECIO" 				as  "UltimoPrecioCompra",
			PUNTAS."SV_PRECIO" 				as  "UltimoPrecioVenta" ,
			'2015-09-22'					as  "FechaCierre",
			0 								as  "ValorContratoUnitario",
			0								as  "ValorContratoEntidad",
			ACMI."VAR_PRE"					as  "VariacionDiaria",
			ACMI."UNI_TRA_DI_AC"			as  "VolumenTransado",			--var_pre? tendencia?
			ACMI."MONTO_DI_AC"				as  "MontoTransado",
			ACMI."PRE_MED_DI_AC"			as  "PrecioMedio",
			ACMI."PRE_CIE_DI_AN" 			as  "PrecioMercadoAnterior"	
FROM "BSCL"."BSCL.Plataforma.BD::INS.Instrumento" INS 
			INNER JOIN  		"RUEBAS"."TBACMI" 	AS ACMI 	ON( ltrim(rtrim(INS."Nemotecnico")) = ltrim(rtrim(ACMI."NEMO")) )
			LEFT OUTER JOIN 	"RUEBAS"."TBTOM" 	AS PUNTAS 	ON(ACMI."NEMO" = PUNTAS.NEMOTE 
																	AND PUNTAS."MERCAD"='AC' 
																	AND LTRIM(PUNTAS.Tipo_Liq)='' AND (PUNTAS.SC_PRECIO <> 0 or PUNTAS.SV_PRECIO <> 0)
																  )
--and Ins."IdTipoInstrumento" = 'ACN';





